// #2a8411 מסך ניהול משתמשים בחברה — состояния, таблица, переход на приглашение (מנהל חשבון).
// Кейсы: .qa/tests/company-users/CU-01..CU-05. Только чтение: ничего не создаётся и не сохраняется.
import { test, expect } from '@playwright/test';
import { authState } from '../helpers/tenderflow';
import {
  COLUMNS, EMPTY_HINT, EMPTY_TITLE, LOADING, MEMBERS_RPC, ROLES, STATUSES,
  dataRows, inviteLinks, openUsers, readRows, usersHeading, usersTable,
} from './users-page';

test.describe('משתמשי החברה — מצבי מסך (חברה B)', () => {
  test.use({ storageState: authState('admin2') });

  test('טעינת רשימת המשתמשים מציגה "טוען משתמשים…" #2a8411 @desktop @prod-safe', async ({ page }) => {
    // CU-01: ответ списка держим, пока не проверена загрузка (без фиксированной паузы).
    let release!: () => void;
    const gate = new Promise<void>((r) => (release = r));
    await page.route(MEMBERS_RPC, async (route) => {
      await gate;
      await route.continue();
    });
    try {
      await page.goto('/users');
      await expect(usersHeading(page)).toBeVisible();
      await expect(page.getByRole('status').filter({ hasText: LOADING })).toBeVisible();
      await expect(usersTable(page)).toHaveCount(0);
    } finally {
      release();
    }
    await expect(dataRows(page).first()).toBeVisible();
    await expect(page.getByText(LOADING)).toHaveCount(0);
    await page.unroute(MEMBERS_RPC);
  });

});

// С 15.11 в компании B постоянный участник «QA Inv14 Member» — пустое состояние проверяем
// в компании «QA add75b בע"מ» (signup14), где только её админ.
test.describe('משתמשי החברה — מצב ריק (חברת signup14)', () => {
  test.use({ storageState: authState('signup14') });

  test('מצב ריק: "אין עדיין משתמשים נוספים בחברה" וכפתור הזמנה #2a8411 @desktop @prod-safe', async ({ page }) => {
    // CU-02: в компании signup14 только её админ.
    await openUsers(page);
    const rows = await readRows(page);
    expect(rows, 'в компании signup14 должен быть только её админ — иначе пустое состояние не проверить').toHaveLength(1);
    expect(rows[0]).toMatchObject({ role: 'מנהל חשבון', status: 'פעיל' });

    const title = page.getByText(EMPTY_TITLE, { exact: true });
    await expect(title).toBeVisible();
    const emptyBlock = title.locator('xpath=..');
    await expect(emptyBlock.getByText(EMPTY_HINT, { exact: true })).toBeVisible();

    const cta = emptyBlock.getByRole('link', { name: 'הזמנת משתמש חדש', exact: true });
    await expect(cta).toBeVisible();
    await cta.click();
    await page.waitForURL('**/users/invite');
    await expect(page.getByRole('heading', { name: 'הזמנת משתמש חדש', level: 1 })).toBeVisible();
  });
});

test.describe('משתמשי החברה — טבלה (חברה A)', () => {
  test.use({ storageState: authState('admin') });

  test('טבלת המשתמשים: עמודות שם · אימייל · טלפון · תפקיד · הרשאה · סטטוס · פעולות #2a8411 @desktop @prod-safe', async ({ page }) => {
    // CU-03
    await openUsers(page);
    await expect(usersTable(page).getByRole('columnheader')).toHaveText([...COLUMNS]);
    const rows = await readRows(page);
    expect(rows.length).toBeGreaterThan(0);
    for (const r of rows) {
      expect(r.email, `email строки «${r.name}»`).toMatch(/^[^\s@]+@[^\s@]+\.[^\s@]+$/);
    }
  });

  test('לכל משתמש מוצגים הרשאה וסטטוס #2a8411 @desktop @prod-safe', async ({ page }) => {
    // CU-04
    await openUsers(page);
    const rows = await readRows(page);
    for (const r of rows) {
      expect(ROLES, `הרשאה у ${r.email}`).toContain(r.role);
      expect(STATUSES, `סטטוס у ${r.email}`).toContain(r.status);
    }
    const roles = new Set(rows.map((r) => r.role));
    expect([...roles].sort()).toEqual([...ROLES].sort());
  });

  test('מעבר למסך הזמנת משתמש חדש וחזרה לרשימה #2a8411 @desktop @prod-safe', async ({ page }) => {
    // CU-05: форма не заполняется и не сохраняется.
    const inviteHeading = page.getByRole('heading', { name: 'הזמנת משתמש חדש', level: 1 });

    await openUsers(page);
    await inviteLinks(page).first().click();
    await page.waitForURL('**/users/invite');
    await expect(inviteHeading).toBeVisible();

    await page.getByRole('link', { name: '← חזרה למשתמשי החברה' }).click();
    await page.waitForURL('**/users');
    await expect(usersHeading(page)).toBeVisible();
    await expect(dataRows(page).first()).toBeVisible();

    await inviteLinks(page).first().click();
    await page.waitForURL('**/users/invite');
    await expect(inviteHeading).toBeVisible();
    await page.getByRole('link', { name: 'ביטול', exact: true }).click();
    await page.waitForURL('**/users');
    await expect(usersHeading(page)).toBeVisible();
    await expect(dataRows(page).first()).toBeVisible();
  });
});
